with checks as ( select 'fn can_manage_client' as thing, exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'can_manage_client') as ok union all select 'videographer cannot write feedback', not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'submission_feedback' and policyname = 'submission_feedback: videographer reply own') union all select 'videographer can still read feedback', exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'submission_feedback' and policyname = 'submission_feedback: videographer read own') union all select 'client can still comment', exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'submission_feedback' and policyname = 'submission_feedback: client comment shared') union all select 'videographer can still add a cut', exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'submission_versions' and policyname = 'submission_versions: videographer add own') union all select 'videographer can still tick the checklist', exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'submission_checklist' and policyname = 'submission_checklist: videographer tick own') union all select 'nobody can approve their own work', not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'submissions' and cmd in ('ALL', 'UPDATE') and coalesce(with_check, '') like '%videographer%') ) select thing, case when ok then 'OK' else 'PROBLEM' end as state from checks order by thing; select tablename, policyname, case when qual like '%can_manage_client%' then 'FIXED' when qual like '%is_management%' then 'ALREADY CORRECT' when qual like '%can_see_client%' then 'STILL WIDE OPEN' else 'CHECK BY HAND' end as state from pg_policies where schemaname = 'public' and (policyname like '%management full access%' or policyname = 'checklist: management full access') order by tablename; select tablename, policyname, case when qual like '%operations_manager%' then 'role-guarded as well' else 'shared with the whole team on purpose' end as note from pg_policies where schemaname = 'public' and qual like '%can_see_client%' and cmd = 'ALL' order by tablename, policyname;
